mapper.select:
SELECT 
  FROM sys51_specific_menu_person
 WHERE sys51_specific_menu_id = #{specificMenuId}
   AND sys51_specific_work_cd = #{specificWorkCd}
 ORDER BY sys51_person_id

SELECT COUNT(*)
  FROM sys50_specific_menu
 WHERE sys50_specific_menu_id = #{specificMenuId}
   AND sys50_company_id       = #{companyId}

mapper.update:
UPDATE sys51_specific_menu_person p
   SET sys51_use_yn = #{req.useYn},
       sys51_note   = #{req.note}
 WHERE sys51_specific_menu_person_id = #{req.specificMenuPersonId}
   AND sys51_specific_menu_id        = #{specificMenuId}
   AND EXISTS (SELECT 1 FROM sys50_specific_menu m
                WHERE m.sys50_specific_menu_id = p.sys51_specific_menu_id AND m.sys50_company_id = #{companyId})

mapper.delete:
DELETE FROM sys51_specific_menu_person p
 WHERE sys51_specific_menu_id = #{specificMenuId}
   AND EXISTS (SELECT 1 FROM sys50_specific_menu m
                WHERE m.sys50_specific_menu_id = p.sys51_specific_menu_id AND m.sys50_company_id = #{companyId})
   AND sys51_specific_menu_person_id IN
#{id}

mapper.insert:
INSERT INTO sys51_specific_menu_person
       (sys51_specific_menu_person_id, sys51_specific_menu_id, sys51_person_id, sys51_use_yn, sys51_note, sys51_specific_work_cd)
SELECT f_create_seq(), m.sys50_specific_menu_id, #{personId}, #{useYn}, #{note}, #{specificWorkCd}
  FROM sys50_specific_menu m
 WHERE m.sys50_specific_work_cd = #{specificWorkCd}
   AND m.sys50_company_id       = #{companyId}
